import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline


cpp_decl = r"""
#include <torch/extension.h>

torch::Tensor cute_scaled_dot_product_attention(
    torch::Tensor Q,
    torch::Tensor K,
    torch::Tensor V);
"""


cuda_src = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>
#include <mma.h>
#include <math_constants.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>
using namespace cute;
using namespace nvcuda;
namespace cute_sdpa_detail {
constexpr int kWarpSize = 32;
constexpr int kThreads = 512;
constexpr int kWarps = kThreads / kWarpSize;
constexpr int kQueryTile = 16;
constexpr int kKeyTile = 16;
constexpr int kHeadDim = 1024;
constexpr int kSmemStride = kHeadDim;
__launch_bounds__(kThreads)
__global__ void cute_sdpa_kernel(
    const __half* __restrict__ q_ptr,
    const __half* __restrict__ k_ptr,
    const __half* __restrict__ v_ptr,
    __half* __restrict__ o_ptr,
    int B,
    int H,
    int S,
    int D)
{
    const int tid = threadIdx.x;
    const int lane = tid & (kWarpSize - 1);
    const int warp = tid >> 5;
    const int b = blockIdx.y;
    const int h = blockIdx.x;
    const int query_base = blockIdx.z * kQueryTile;
    extern __shared__ unsigned char smem_raw[];
    __half (*smem_q)[16] = reinterpret_cast<__half (*)[16]>(smem_raw);
    __half (*smem_k)[16] = reinterpret_cast<__half (*)[16]>(
        smem_raw + kQueryTile * 16 * sizeof(__half));
    float (*smem_scores)[256] = reinterpret_cast<float (*)[256]>(
        smem_raw + kQueryTile * 16 * sizeof(__half) +
        16 * 16 * sizeof(__half) * kWarps);
    __half (*smem_v)[kHeadDim] = reinterpret_cast<__half (*)[kHeadDim]>(
        smem_raw + kQueryTile * 16 * sizeof(__half) +
        16 * 16 * sizeof(__half) * kWarps +
        kQueryTile * 256 * sizeof(float));
    const long long base =
        static_cast<long long>(b) * H * S * D +
        static_cast<long long>(h) * S * D;
    const int num_key_tiles = (S + 15) / 16;
    for (int key_tile = 0; key_tile < num_key_tiles; ++key_tile) {
        wmma::fragment<wmma::accumulator, 16, 16, 16, float> score_acc;
        wmma::fill_fragment(score_acc, 0.0f);
        for (int kb = 0; kb < D; kb += 16) {
            for (int linear = tid; linear < kQueryTile * 16;
                 linear += kThreads) {
                const int qr = linear / 16;
                const int d = linear & 15;
                const int q = query_base + qr;
                smem_q[qr][d] = q < S
                    ? q_ptr[base + static_cast<long long>(q) * D + kb + d]
                    : __float2half(0.0f);
            }
            for (int linear = lane; linear < 16 * 16;
                 linear += kWarpSize) {
                const int d = linear / 16;
                const int kk = linear & 15;
                const int key = key_tile * 16 + kk;
                smem_k[warp * 16 + d][kk] = key < S
                    ? k_ptr[base + static_cast<long long>(key) * D + kb + d]
                    : __float2half(0.0f);
            }
            __syncthreads();
            wmma::fragment<wmma::matrix_a, 16, 16, 16, __half,
                           wmma::row_major> a_frag;
            wmma::fragment<wmma::matrix_b, 16, 16, 16, __half,
                           wmma::row_major> b_frag;
            wmma::load_matrix_sync(a_frag, &smem_q[0][0], 16);
            wmma::load_matrix_sync(b_frag, &smem_k[warp * 16][0], 16);
            wmma::mma_sync(score_acc, a_frag, b_frag, score_acc);
            __syncthreads();
        }
        if (warp == 0) {
            wmma::store_matrix_sync(
                &smem_scores[0][key_tile * 16],
                score_acc,
                256,
                wmma::mem_row_major);
        }
        __syncthreads();
    }
    __syncthreads();
    float accum[2][kHeadDim / kWarpSize];
    #pragma unroll
    for (int r = 0; r < 1; ++r) {
        #pragma unroll
        for (int i = 0; i < kHeadDim / kWarpSize; ++i) {
            accum[r][i] = 0.0f;
        }
    }
    constexpr float scale = 1.0f / 32.0f;
    float max_logit[2] = {
        -CUDART_INF_F,
        -CUDART_INF_F
    };
    float norm[2] = {0.0f, 0.0f};
    for (int key_base = 0; key_base < S; key_base += 16) {
        for (int linear = tid; linear < 16 * kHeadDim; linear += kThreads) {
            const int kk = linear / kHeadDim;
            const int d = linear & (kHeadDim - 1);
            const int key = key_base + kk;
            smem_v[kk][d] = key < S
                ? v_ptr[base + static_cast<long long>(key) * D + d]
                : __float2half(0.0f);
        }
        __syncthreads();
        #pragma unroll
        for (int r = 0; r < 1; ++r) {
            const int q_local = warp + r * kWarps;
            const int q_idx = query_base + q_local;
            for (int kk = 0; kk < 16; ++kk) {
                const int key = key_base + kk;
                const float logit = (q_idx < S && key < S)
                    ? smem_scores[q_local][key] * scale
                    : -CUDART_INF_F;
                const float new_max = fmaxf(max_logit[r], logit);
                const float old_weight = max_logit[r] == -CUDART_INF_F
                    ? 0.0f
                    : expf(max_logit[r] - new_max);
                const float new_weight = logit == -CUDART_INF_F
                    ? 0.0f
                    : expf(logit - new_max);
                #pragma unroll
                for (int i = 0; i < kHeadDim / kWarpSize; ++i) {
                    const int d = lane + i * kWarpSize;
                    accum[r][i] = accum[r][i] * old_weight +
                        __half2float(smem_v[kk][d]) * new_weight;
                }
                norm[r] = norm[r] * old_weight + new_weight;
                max_logit[r] = new_max;
            }
        }
        __syncthreads();
    }
    #pragma unroll
    for (int r = 0; r < 1; ++r) {
        const int q_local = warp + r * kWarps;
        const int q_idx = query_base + q_local;
        if (q_idx < S) {
            const float inv_norm = 1.0f / norm[r];
            #pragma unroll
            for (int i = 0; i < kHeadDim / kWarpSize; ++i) {
                const int d = lane + i * kWarpSize;
                o_ptr[base + static_cast<long long>(q_idx) * D + d] =
                    __float2half_rn(accum[r][i] * inv_norm);
            }
        }
    }
}
} // namespace cute_sdpa_detail


torch::Tensor cute_scaled_dot_product_attention(
    torch::Tensor Q,
    torch::Tensor K,
    torch::Tensor V)
{
    TORCH_CHECK(Q.is_cuda() && K.is_cuda() && V.is_cuda(),
                "Q, K, and V must be CUDA tensors");
    TORCH_CHECK(Q.scalar_type() == at::kHalf &&
                K.scalar_type() == at::kHalf &&
                V.scalar_type() == at::kHalf,
                "Q, K, and V must be float16 tensors");
    TORCH_CHECK(Q.dim() == 4 && K.dim() == 4 && V.dim() == 4,
                "Q, K, and V must be 4D tensors");

    const int B = static_cast<int>(Q.size(0));
    const int H = static_cast<int>(Q.size(1));
    const int S = static_cast<int>(Q.size(2));
    const int D = static_cast<int>(Q.size(3));

    TORCH_CHECK(K.size(0) == B && K.size(1) == H &&
                K.size(2) == S && K.size(3) == D,
                "K shape must match Q shape");
    TORCH_CHECK(V.size(0) == B && V.size(1) == H &&
                V.size(2) == S && V.size(3) == D,
                "V shape must match Q shape");
    TORCH_CHECK(S > 0 && S <= 256,
                "Sequence length must be in the range [1, 256]");
    TORCH_CHECK(
        D == cute_sdpa_detail::kHeadDim,
        "Head dimension must be ",
        cute_sdpa_detail::kHeadDim);
    auto Qc = Q.contiguous();
    auto Kc = K.contiguous();
    auto Vc = V.contiguous();
    auto O = torch::empty_like(Qc);

    dim3 block(cute_sdpa_detail::kThreads);
    dim3 grid(H, B, (S + cute_sdpa_detail::kQueryTile - 1) / cute_sdpa_detail::kQueryTile);
    constexpr size_t smem_bytes =
        cute_sdpa_detail::kQueryTile * 16 * sizeof(__half) +
        16 * 16 * cute_sdpa_detail::kWarps * sizeof(__half) +
        cute_sdpa_detail::kQueryTile * 256 * sizeof(float) +
        16 * cute_sdpa_detail::kHeadDim * sizeof(__half);
    cudaError_t err = cudaFuncSetAttribute(
        cute_sdpa_detail::cute_sdpa_kernel,
        cudaFuncAttributeMaxDynamicSharedMemorySize,
        static_cast<int>(smem_bytes));
    TORCH_CHECK(err == cudaSuccess,
                "cudaFuncSetAttribute failed: ",
                cudaGetErrorString(err));
    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
    cute_sdpa_detail::cute_sdpa_kernel<<<grid, block, smem_bytes, stream>>>(
        reinterpret_cast<const __half*>(Qc.data_ptr<at::Half>()),
        reinterpret_cast<const __half*>(Kc.data_ptr<at::Half>()),
        reinterpret_cast<const __half*>(Vc.data_ptr<at::Half>()),
        reinterpret_cast<__half*>(O.data_ptr<at::Half>()),
        B,
        H,
        S,
        D);
    err = cudaGetLastError();
    TORCH_CHECK(err == cudaSuccess,
                "CuTE scaled dot-product attention kernel launch failed: ",
                cudaGetErrorString(err));
    err = cudaStreamSynchronize(stream);
    TORCH_CHECK(err == cudaSuccess,
                "CuTE scaled dot-product attention kernel execution failed: ",
                cudaGetErrorString(err));

    return O;
}
"""


cute_ext = load_inline(
    name="cute_sdpa_ext",
    cpp_sources=cpp_decl,
    cuda_sources=cuda_src,
    functions=["cute_scaled_dot_product_attention"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=[
        "-O3",
        "-I/root/cutegen_test/cutegen/cutlass/include",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()
        self._ext = cute_ext

    def forward(
        self,
        Q: torch.Tensor,
        K: torch.Tensor,
        V: torch.Tensor,
    ) -> torch.Tensor:
        return self._ext.cute_scaled_dot_product_attention(Q, K, V)

